{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind kind, COUNT(*) n, ROUND(quantile_cont(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name IN ('SELECT ts.trip2','Transaction.commit') GROUP BY 1,2,3", "claim": "Travel2's own DB spans (SELECT ts.trip2, Transaction.commit) have p95 of about 640–860 ms in abnormal, versus about 0.2–0.3 ms normal."},
        {"kind": "trace", "sql": "WITH t AS (SELECT 'n' p, * FROM normal_traces UNION ALL SELECT 'a', * FROM abnormal_traces) SELECT p, span_name, COUNT(*) n, ROUND(quantile_cont(duration/1e6,0.95),1) p95 FROM t WHERE service_name='ts-travel2-service' AND span_name IN ('TripRepository.findAll','TripRepository.findByRouteId') GROUP BY 1,2 ORDER BY 2,1", "claim": "Travel2 repository lookups slow from about 2 ms to 830–3370 ms p95, while travel2's HTTP GET spans stay near 2 ms."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, COUNT(*) n, ROUND(quantile_cont(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel-service' AND span_name IN ('SELECT ts.trip','TripRepository.findAll') GROUP BY 1,2", "claim": "The sibling ts-travel-service uses its own DB normally (about 0.2 ms client SELECT), so the slowness is specific to travel2's DB calls."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-travel2-service", "to": "ts-route-plan-service",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind kind, COUNT(*) n, ROUND(quantile_cont(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Client' AND span_name='POST' GROUP BY 1,2,3", "claim": "Route-plan's client calls to travel2 for trips/routes have p95 of about 1909 ms, against about 48 ms normal."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind kind, COUNT(*) n, ROUND(quantile_cont(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND span_name LIKE 'POST /api/v1/travelplanservice/travelPlan/quickest%' GROUP BY 1,2,3", "claim": "Travel-plan quickest endpoint server p95 rises to about 2183 ms, tracking route-plan's slow quickestRoute calls."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard",
     "evidence": [{"kind": "trace", "sql": "SELECT p, service_name, span_name, COUNT(*) n, ROUND(quantile_cont(duration/1e6,0.95),1) p95 FROM (SELECT 'n' p, * FROM normal_traces UNION ALL SELECT 'a', * FROM abnormal_traces) t WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%travelPlan%' GROUP BY 1,2,3 ORDER BY 3,1", "claim": "UI dashboard's travelPlan endpoints slow to about 2.3 s p95 in abnormal, versus about 100 ms normal."}]},
    {"from": "ts-travel2-service", "to": "ts-admin-travel-service",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind kind, COUNT(*) n, ROUND(quantile_cont(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-admin-travel-service' AND attr_span_kind='Client' GROUP BY 1,2,3", "claim": "Admin-travel's client GET calls to travel2 have p95 of about 1915 ms in abnormal."}]},
    {"from": "ts-admin-travel-service", "to": "ts-ui-dashboard",
     "evidence": [{"kind": "trace", "sql": "SELECT p, service_name, span_name, COUNT(*) n, ROUND(quantile_cont(duration/1e6,0.95),1) p95 FROM (SELECT 'n' p, * FROM normal_traces UNION ALL SELECT 'a', * FROM abnormal_traces) t WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%admintravelservice%' GROUP BY 1,2,3 ORDER BY 3,1", "claim": "UI dashboard GET admintravel p95 rises from about 68 ms to about 2103 ms."}]},
    {"from": "ts-travel2-service", "to": "ts-ui-dashboard",
     "evidence": [{"kind": "trace", "sql": "SELECT p, service_name, span_name, COUNT(*) n, ROUND(quantile_cont(duration/1e6,0.95),1) p95 FROM (SELECT 'n' p, * FROM normal_traces UNION ALL SELECT 'a', * FROM abnormal_traces) t WHERE service_name='ts-ui-dashboard' AND span_name='POST /api/v1/travel2service/trips/left' GROUP BY 1,2,3", "claim": "User-facing POST travel2service/trips/left at UI dashboard rises from about 52 ms to about 3170 ms p95."}]}
  ]
}
